<template>
  <AppForm ref="form" :model="model" class="report-editor" data-screenshot-editor="own" @paste.capture="blockReportImages" @drop.capture="blockReportImages" @submit.prevent>
    <div v-if="!planning&&!singleTask" class="lunch-report-tools"><span>是否有中午加班？</span><el-radio-group v-if="editable" :model-value="lunchChoice" @update:model-value="setLunchChoice"><el-radio :value="true">有</el-radio><el-radio :value="false">无</el-radio></el-radio-group><el-tag v-else :type="lunchChoice?'warning':'info'">{{lunchChoice?'有中午加班':'无中午加班'}}</el-tag>
      <template v-if="lunchChoice"><el-alert title="声明：我确认中午确实有加班，且没有顺延下午上班时间。请如实填写12:00–13:30内的实际项目和时段；各项目时段不得重叠。" type="warning" :closable="false" /><el-checkbox v-if="editable" :model-value="lunchConfirmed" @update:model-value="confirmLunch">我确认上述中午加班声明</el-checkbox><el-button v-if="editable" :disabled="!lunchConfirmed" @click="addLunch">新增中午加班行</el-button></template>
    </div>
    <div class="report-project-filter"><el-input v-model="projectFilter" placeholder="筛选项目名称或订单号" clearable aria-label="工作报告项目筛选" /><el-checkbox v-model="onlyLunch">仅看中午加班</el-checkbox><span>筛选只影响查看，保存仍包含全部工作记录。</span></div>
    <div class="report-editor__scroll" v-loading="loading">
      <table class="report-grid"><thead><tr><th class="index">序号</th><th class="types">任务/项目类型（可多选）</th><th class="order">订单号</th><th class="project">项目名称</th><th class="task">具体任务</th><th class="quantity">工作量</th><th class="unit">单位</th><th class="duration">{{planning?'预计需要时间':'耗时'}}</th><th class="action"></th></tr></thead>
      <tbody><tr v-for="(row,index) in model.rows" :key="reportRowKey(row)" v-show="matchesRow(row)" :class="{'is-system':row.source_type==='system_event','is-child':parentRowKey(row),'is-lunch-overtime':row.display_metadata.lunch_overtime}">
        <td class="index"><strong>{{outline[index]}}</strong><el-tag v-if="row.display_metadata.lunch_overtime" type="warning" size="small">中午加班</el-tag><small v-if="parentRowKey(row)" class="child-label">└ 二级</small><small v-if="row.source_type==='system_event'" title="系统记录自动汇总">系统</small></td>
        <td><span v-if="parentRowKey(row)" class="inherited">↳ 类型随上级</span><template v-else><el-form-item data-dialog-field-search-label="任务类型" :prop="`rows.${index}.display_metadata.report_types`" :rules="[{type:'array',required:!locked(row),min:1,message:'请选择类型',trigger:'change'}]"><el-cascader :show-all-levels="false" :model-value="row.display_metadata.report_types" :options="typeOptions" :props="{multiple:true,emitPath:false}" filterable collapse-tags collapse-tags-tooltip :disabled="locked(row)||(singleTask&&!planning)" :aria-label="`第${index+1}行任务类型`" @update:model-value="updateTypes(row,$event)"></el-cascader></el-form-item><el-form-item v-if="row.display_metadata.report_types.includes('其他项目')" :prop="`rows.${index}.display_metadata.custom_project_type`" :rules="[{required:true,whitespace:true,message:'填写具体项目类型',trigger:'blur'}]"><el-input v-model="row.display_metadata.custom_project_type" placeholder="具体项目类型" :disabled="locked(row)||!canAddProjectCategory" maxlength="80" @input="changed" /></el-form-item><el-form-item v-for="parent in customParents(row)" :key="parent" :prop="`rows.${index}.display_metadata.custom_work_types.${parent}`" :rules="[{required:true,whitespace:true,message:'请输入具体'+parent,trigger:'blur'}]"><el-input v-model="row.display_metadata.custom_work_types[parent]" :placeholder="'请输入具体'+parent" :aria-label="'具体'+parent" :disabled="locked(row)" maxlength="80" @input="changed" /></el-form-item></template></td>
        <td><el-form-item data-dialog-field-search-label="订单号" :prop="`rows.${index}.display_metadata.order_no`" :rules="[{required:!locked(row)&&requiresProjectIdentity(row),whitespace:true,message:'请填写订单号',trigger:'blur'}]"><ReadonlyField v-if="parentRowKey(row)||(singleTask&&!planning)||row.display_metadata.project_id" :model-value="row.display_metadata.order_no || '随上级'" source="auto" /><el-input v-else v-model="row.display_metadata.order_no" :aria-label="`第${index+1}行订单号`" :disabled="locked(row)" maxlength="100" @input="orderInput(row)" @blur="checkOrder(row)" @change="checkOrder(row)" @paste="paste($event,index,0)" /></el-form-item></td>
        <td><el-form-item data-dialog-field-search-label="项目名称" :prop="`rows.${index}.task_name`" :rules="[{required:!locked(row)&&requiresProjectIdentity(row),whitespace:true,message:'请填写项目名称',trigger:'blur'}]"><span v-if="parentRowKey(row)" class="inherited">↳ 项目随上级</span><ReadonlyField v-else-if="row.display_metadata.project_id" :model-value="row.task_name" source="auto" /><el-input v-else v-model="row.task_name" type="textarea" :autosize="{minRows:2,maxRows:5}" :aria-label="`第${index+1}行项目名称`" :disabled="locked(row)" maxlength="255" @input="changed" @paste="paste($event,index,1)" /><el-button v-if="!locked(row)&&(!singleTask||planning)&&!parentRowKey(row)&&projectType(row)" type="primary" link @click="openProjectPicker(row)">选择项目</el-button></el-form-item></td>
        <td><el-form-item data-dialog-field-search-label="具体任务" :prop="`rows.${index}.progress_content`" :rules="[{required:!locked(row),whitespace:true,message:'填写具体任务',trigger:'blur'}]"><el-autocomplete v-model="row.progress_content" type="textarea" :autosize="{minRows:2,maxRows:6}" :fetch-suggestions="suggest" :trigger-on-focus="true" :aria-label="`第${index+1}行具体任务`" :disabled="locked(row)" maxlength="10000" placeholder="填写或选择历史任务" @input="changed" @change="remember(row.progress_content)" @select="remember(row.progress_content);changed()" @paste="paste($event,index,2)" /></el-form-item><small v-if="row.result_content" class="old-result">原工作成果：{{row.result_content}}</small></td>
        <td><el-form-item data-dialog-field-search-label="工作量" :prop="`rows.${index}.display_metadata.quantity`" :rules="[{required:!locked(row),validator:(_rule,value,done)=>locked(row)?done():quantityRule(_rule,value,done),trigger:'blur'}]"><el-input v-model="row.display_metadata.quantity" inputmode="decimal" :aria-label="`第${index+1}行工作量`" :disabled="locked(row)" @input="changed" @paste="paste($event,index,3)" /></el-form-item></td>
        <td><el-form-item data-dialog-field-search-label="单位" :prop="`rows.${index}.display_metadata.quantity_unit`" :rules="[{validator:(_rule,value,done)=>done(!locked(row)&&(!planning||row.display_metadata.quantity!==''&&row.display_metadata.quantity!=null)&&!value?.trim()?new Error('请选择单位'):undefined),trigger:'change'}]"><el-select v-model="row.display_metadata.quantity_unit" filterable allow-create default-first-option clearable :aria-label="`第${index+1}行单位`" :disabled="locked(row)" placeholder="选择/输入" @change="changed"><el-option v-for="unit in units" :key="unit" :value="unit" :label="unit==='其他'?'其他（填写单位）':unit" /></el-select></el-form-item><el-form-item v-if="row.display_metadata.quantity_unit==='其他'" :prop="`rows.${index}.display_metadata.quantity_unit_other`" :rules="[{required:true,whitespace:true,message:'填写具体单位',trigger:'blur'}]"><el-input v-model="row.display_metadata.quantity_unit_other" placeholder="具体单位" :disabled="locked(row)" @input="changed" /></el-form-item></td>
        <td><template v-if="row.display_metadata.lunch_overtime"><el-form-item label="午间开始" :prop="`rows.${index}.display_metadata.lunch_start`" :rules="[{required:true,message:'请选择午间开始时间',trigger:'change'}]"><el-time-picker v-model="row.display_metadata.lunch_start" format="HH:mm" value-format="HH:mm" :disabled="locked(row)" :aria-label="`第${index+1}行午间开始`" @change="lunchTimeChanged(row)" /></el-form-item><el-form-item label="午间结束" :prop="`rows.${index}.display_metadata.lunch_end`" :rules="[{required:true,validator:(_rule,_value,done)=>done(validLunch(row)?undefined:new Error('时段须在12:00–13:30内且结束晚于开始')),trigger:'change'}]"><el-time-picker v-model="row.display_metadata.lunch_end" format="HH:mm" value-format="HH:mm" :disabled="locked(row)" :aria-label="`第${index+1}行午间结束`" @change="lunchTimeChanged(row)" /></el-form-item><ReadonlyField :model-value="durationLabel(row.duration_minutes)" source="auto" /></template><el-form-item v-else data-dialog-field-search-label="耗时" :prop="`rows.${index}.duration_minutes`" :rules="[{required:!locked(row),validator:(_rule,value,done)=>done(!locked(row)&&!planning&&!(Number(value)>0)?new Error('请选择耗时'):undefined),trigger:'change'}]"><el-select v-model="row.duration_minutes" filterable :aria-label="`第${index+1}行耗时`" :disabled="locked(row)" @change="changed"><el-option :value="0" label="未填写" /><el-option v-if="row.duration_minutes && !durationOptions.includes(row.duration_minutes)" :value="row.duration_minutes" :label="`${durationLabel(row.duration_minutes)}（${row.duration_minutes}分钟）`" /><el-option v-for="minutes in durationOptions" :key="minutes" :value="minutes" :label="durationLabel(minutes)" /></el-select></el-form-item></td>
        <td class="row-actions"><el-popover v-if="editable&&!singleTask&&!row.display_metadata.lunch_overtime" trigger="click" placement="left" :width="250"><div class="child-actions"><span>在本项目下新增二级工作行</span><el-input-number v-model="childCount" :min="1" :max="100" :precision="0" :aria-label="`第${index+1}行下级行数`" /><el-button type="primary" @click="addChildren(row,childCount)">生成下级</el-button></div><template #reference><el-button link type="primary" :aria-label="`第${index+1}行新增下级`">新增下级</el-button></template></el-popover><el-button v-if="editable&&!singleTask&&row.source_type==='manual'&&row.display_metadata?.source!=='consultation_handoff'" link type="danger" :aria-label="`删除第${index+1}行`" @click="remove(index)">删除</el-button></td>
      </tr><tr v-if="!model.rows.length"><td colspan="9" class="empty">暂无工作记录，点击“新增一行”填写。</td></tr></tbody></table>
    </div>
    <footer><template v-if="editable&&!singleTask"><el-button @click="add()">＋ 新增一行</el-button><el-input-number v-model="addCount" :min="1" :max="100" :precision="0" :step="1" step-strictly aria-label="新增行数" /><el-button @click="add(addCount)">新增多行</el-button></template><span>合计 {{durationLabel(total)}}（{{total}}分钟）</span><small>Tab 切换单元格；支持从 Excel 粘贴文字；所有字段禁止截图。仅非项目工作免填订单号和项目名称。</small></footer>
  </AppForm>
  <ReportProjectPicker v-model="projectPickerVisible" :project-type="pickerType" @selected="applyProject" />
</template>
<script setup>
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import ReadonlyField from '@/components/common/ReadonlyField.vue'
import ReportProjectPicker from '@/components/common/ReportProjectPicker.vue'
import {reportRowKey,parentRowKey,reportOutline,syncReportChildren,nestDuplicateOrder,appendChildRows,ensureReportKeys} from '@/utils/workReportHierarchy'
import {createDailyReportCategory} from '@/api/tasks'
import {matchesSearch} from '@/utils/searchMatching'
import {durationLabel,durationOptions,newReportRow,normalizeReportRow,updateRowTypes,validQuantity,buildWorkTypeOptions,defaultWorkCategories,appendReportRows,blockReportImages,requiresProjectIdentity,categoryValue} from '@/utils/workReportForm'
const props=defineProps({rows:{type:Array,default:()=>[]},singleTask:Boolean,planning:Boolean,editable:Boolean,loading:Boolean,categories:{type:Object,default:()=>defaultWorkCategories},canAddProjectCategory:Boolean,categoryStorageReady:Boolean,history:{type:Array,default:()=>[]}})
const emit=defineEmits(['dirty-change','remember','categories-change'])
const model=reactive({rows:[]}),form=ref(),dirty=ref(0)
const addCount=ref(5),childCount=ref(1),lunchChoice=ref(false),lunchConfirmed=ref(false),projectFilter=ref(''),appliedProjectFilter=ref(''),onlyLunch=ref(false)
let filterTimer
watch(projectFilter,value=>{clearTimeout(filterTimer);if(!value)appliedProjectFilter.value='';else filterTimer=setTimeout(()=>{appliedProjectFilter.value=value},400)})
const matchesRow=row=>(!onlyLunch.value||row.display_metadata.lunch_overtime)&&matchesSearch(`${row.task_name} ${row.display_metadata.order_no||''}`,appliedProjectFilter.value)
const projectPickerVisible=ref(false),pickerType=ref('')
let pickerRow=null,pickerBackup=null
const searchableProjectTypes=['笔译项目','口译项目','招聘项目','标注项目','配音项目','字幕项目','公证项目','认证项目','新咨询对接']
function projectType(row){return row.display_metadata.report_types.find(type=>searchableProjectTypes.includes(type))}
function openProjectPicker(row){const type=projectType(row);if(!type)return;pickerRow=row;pickerType.value=type;projectPickerVisible.value=true}
function applyProject(project){
  if(!pickerRow||!model.rows.includes(pickerRow))return
  pickerRow.task_name=project.project_name.slice(0,255)
  Object.assign(pickerRow.display_metadata,{order_no:project.order_no,project_id:project.id,selected_project_type:project.project_type,selected_project_name:project.project_name})
  pickerBackup=null;pickerRow=null;form.value?.clearValidate();changed()
}
watch(projectPickerVisible,visible=>{if(!visible){if(pickerRow&&pickerBackup&&model.rows.includes(pickerRow)){pickerRow.task_type=pickerBackup.task_type;pickerRow.task_name=pickerBackup.task_name;pickerRow.display_metadata=pickerBackup.display_metadata;changed()}pickerRow=null;pickerBackup=null}})
const outline=computed(()=>reportOutline(model.rows))
const typeOptions=computed(()=>buildWorkTypeOptions(props.categories,model.rows).map(group=>({...group,children:group.children.map(option=>({...option,disabled:option.value==='其他项目'&&!props.canAddProjectCategory&&!model.rows.some(row=>row.display_metadata.custom_project_type)}))})))
const units=['个','份','页','字','次','其他']
watch(()=>props.rows,rows=>{model.rows=rows.map(row=>{const value=normalizeReportRow(row);value.display_metadata.custom_work_types={...(value.display_metadata.custom_work_types||{})};return value});ensureReportKeys(model.rows);syncReportChildren(model.rows);lunchChoice.value=model.rows.some(row=>row.display_metadata.lunch_overtime);lunchConfirmed.value=lunchChoice.value&&model.rows.filter(row=>row.display_metadata.lunch_overtime).every(row=>row.display_metadata.lunch_overtime_confirmed===true);dirty.value=0},{immediate:true})
const total=computed(()=>model.rows.reduce((sum,row)=>sum+(Number(row.duration_minutes)||0),0))
const locked=row=>!props.editable||row.source_type==='system_event'
function changed(){if(!props.editable)return;syncReportChildren(model.rows);dirty.value++;emit('dirty-change',dirty.value)}
function setLunchChoice(value){if(!value&&model.rows.some(row=>row.display_metadata.lunch_overtime)){ElMessage.warning('请先删除中午加班行，再选择无');return}lunchChoice.value=value;if(value&&!model.rows.some(row=>row.display_metadata.lunch_overtime))lunchConfirmed.value=false;changed()}
function confirmLunch(value){lunchConfirmed.value=value;for(const row of model.rows)if(row.display_metadata.lunch_overtime)row.display_metadata.lunch_overtime_confirmed=value;changed()}
function addLunch(){if(!lunchConfirmed.value)return;const row=newReportRow();Object.assign(row.display_metadata,{lunch_overtime:true,lunch_overtime_confirmed:true,lunch_start:'',lunch_end:''});model.rows.push(row);ensureReportKeys(model.rows);changed()}
const minute=value=>{const [h,m]=String(value||'').split(':').map(Number);return h*60+m}
const validLunch=row=>minute(row.display_metadata.lunch_start)>=720&&minute(row.display_metadata.lunch_end)<=810&&minute(row.display_metadata.lunch_end)>minute(row.display_metadata.lunch_start)
function lunchTimeChanged(row){row.duration_minutes=validLunch(row)?minute(row.display_metadata.lunch_end)-minute(row.display_metadata.lunch_start):0;changed()}
function customParents(row){return row.display_metadata.report_types.filter(value=>value.endsWith('::__custom__')).map(value=>value.split('::')[0])}
function updateTypes(row,types){
  if(locked(row)||types.length===row.display_metadata.report_types.length&&types.every(value=>row.display_metadata.report_types.includes(value)))return
  const selected=types.filter(type=>searchableProjectTypes.includes(type))
  if(selected.length>1){ElMessage.warning('一行只能关联一种项目类型，请新增一行填写其他项目');return}
  const previous=projectType(row),backup={task_type:row.task_type,task_name:row.task_name,display_metadata:JSON.parse(JSON.stringify(row.display_metadata))}
  row.display_metadata.custom_work_types||={};updateRowTypes(row,types)
  if(previous!==selected[0]){delete row.display_metadata.project_id;delete row.display_metadata.selected_project_type;delete row.display_metadata.selected_project_name;if(previous){row.display_metadata.order_no='';row.task_name=''}}
  form.value?.clearValidate();changed()
  if(selected.length&&previous!==selected[0]){pickerBackup=backup;openProjectPicker(row)}
}
function remember(value){if(value?.trim())emit('remember',value.trim())}
function suggest(query,callback){callback(props.history.filter(value=>matchesSearch(value,query)).slice(0,30).map(value=>({value})))}
function quantityRule(_rule,value,done){done(props.planning&&(value===''||value==null)||value!==''&&value!=null&&validQuantity(value)?undefined:new Error('请填写非负数字工作量'))}
function add(count=1){if(!props.editable)return;try{appendReportRows(model.rows,count);changed()}catch(error){ElMessage.warning(error.message)}}
function remove(index){if(model.rows.some(row=>parentRowKey(row)===reportRowKey(model.rows[index]))){ElMessage.warning('请先删除该项目的下级工作行');return}model.rows.splice(index,1);changed()}
const orderTimers=new Map()
function orderInput(row){changed();clearTimeout(orderTimers.get(reportRowKey(row)));orderTimers.set(reportRowKey(row),setTimeout(()=>checkOrder(row),400))}
function checkOrder(row){clearTimeout(orderTimers.get(reportRowKey(row)));if(!model.rows.includes(row))return;if(nestDuplicateOrder(model.rows,row)){ElMessageBox.alert('同一个项目应当填写在下一级！','重复订单号',{confirmButtonText:'知道了'}).catch(()=>{});form.value?.clearValidate();changed()}}
onBeforeUnmount(()=>{clearTimeout(filterTimer);for(const timer of orderTimers.values())clearTimeout(timer)})
function addChildren(row,count){try{appendChildRows(model.rows,row,count);changed();form.value?.clearValidate()}catch(error){ElMessage.warning(error.message)}}
function paste(event,index,column){
  if(!props.editable||blockReportImages(event))return
  if(props.singleTask&&(event.clipboardData?.getData('text/plain')||'').includes('\t')){event.preventDefault();ElMessage.warning('请逐项填写当前任务');return}
  const text=event.clipboardData?.getData('text/plain')||'';if(!text.includes('\t'))return
  event.preventDefault()
  const rows=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(line=>line.split('\t'))
  for(let r=0;r<rows.length;r++){
    if(!model.rows[index+r])model.rows.push(newReportRow())
    const row=model.rows[index+r];if(locked(row))continue
    rows[r].forEach((value,c)=>{switch(column+c){case 0:if(parentRowKey(row))break;row.display_metadata.order_no=value.slice(0,100);break;case 1:if(parentRowKey(row))break;row.task_name=value.slice(0,255);break;case 2:row.progress_content=value.slice(0,10000);remember(value);break;case 3:row.display_metadata.quantity=value;break;case 4:row.display_metadata.quantity_unit=value;break;case 5:{const n=Number(value.replace(/分钟|小时/g,''));if(Number.isFinite(n))row.duration_minutes=Math.min(1440,Math.max(0,Math.round(n*(value.includes('小时')?60:1))));break}}})
  }
  for(const row of [...model.rows].reverse())if(nestDuplicateOrder(model.rows,row))ElMessage.info('同一个项目应当填写在下一级！')
  changed()
}
function getRows(){syncReportChildren(model.rows);model.rows.forEach(row=>remember(row.progress_content));return model.rows.map(row=>({...row,display_metadata:{...row.display_metadata}}))}
async function validate(){projectFilter.value='';appliedProjectFilter.value='';onlyLunch.value=false;if(lunchChoice.value&&!model.rows.some(row=>row.display_metadata.lunch_overtime)){ElMessage.error('请新增中午加班行并填写实际项目和时段');throw new Error('请填写中午加班')}if(model.rows.some(row=>row.display_metadata.lunch_overtime)&&!lunchConfirmed.value){ElMessage.error('请先确认中午确实加班且未顺延下午上班');throw new Error('请确认中午加班声明')}const lunchWindows=model.rows.filter(row=>row.display_metadata.lunch_overtime).map(row=>[minute(row.display_metadata.lunch_start),minute(row.display_metadata.lunch_end)]).sort((a,b)=>a[0]-b[0]);if(lunchWindows.some((row,index)=>index&&lunchWindows[index-1][1]>row[0])){ElMessage.error('中午加班时段不能重叠');throw new Error('中午加班时段重叠')}syncReportChildren(model.rows);await form.value.validate();for(const row of model.rows){if(props.canAddProjectCategory&&row.display_metadata.report_types.includes('其他项目')&&row.display_metadata.custom_project_type?.trim()!=='其他项目'){const name=row.display_metadata.custom_project_type.trim();try{const data=await createDailyReportCategory({parent:'项目工作',name});emit('categories-change',data);updateRowTypes(row,row.display_metadata.report_types.map(value=>value==='其他项目'?categoryValue('项目工作',name):value));delete row.display_metadata.custom_project_type}catch(error){ElMessage.error(error.detail||'保存自定义项目选项失败');throw error}}for(const parent of customParents(row)){const name=row.display_metadata.custom_work_types[parent].trim();let data;try{data=await createDailyReportCategory({parent,name})}catch(error){ElMessage.error(error.detail||'保存自定义工作选项失败');throw error}emit('categories-change',data);updateRowTypes(row,row.display_metadata.report_types.map(value=>value===`${parent}::__custom__`?categoryValue(parent,name):value))}delete row.display_metadata.custom_work_types}return true}
defineExpose({getRows,validate,add})
</script>
